                if($kind==='standalone'&&$row['bound_currency']!==null)$row['bound_currency_iso']=(new CompanyCurrencyUnits($this->db,$this->prefix))->resolveRead($row['bound_currency'])['iso_code'];$row['available']=$row['stopped_at']!==null&&$row['allocation_state']===null;
